module PPOCR.StyleCss

let file = """:root{color-scheme:dark;font-family:Inter,ui-sans-serif,system-ui,sans-serif;background:#111416;color:#e0e7e5;--line:#303a3b;--muted:#8fa5a3;--accent:#a2e7ce}
[hidden]{display:none!important}
h1 span{font-size:22px;letter-spacing:-.7px;color:var(--muted);font-weight:400}
#mirage-options{margin-top:18px;border:1px solid var(--line);border-radius:9px;padding:16px;background:linear-gradient(110deg,#172425,#151b20)}
.settings-row{display:flex;flex-wrap:wrap;align-items:center;gap:16px}.settings-row label{display:flex;gap:8px;align-items:center;font-size:12px;color:var(--muted)}.model-note{font:11px/1.6 ui-monospace,monospace;color:var(--muted);margin-left:auto}
input[type=number],input[type=text]{color:inherit;background:#11191a;border:1px solid var(--line);border-radius:5px;padding:8px;font:inherit}input[type=number]{width:75px}input[type=checkbox]{accent-color:var(--accent)}
fieldset{display:flex;flex-wrap:wrap;gap:15px;border:0;padding:8px 0;margin:12px 0;font-size:12px}legend{font-size:10px;text-transform:uppercase;letter-spacing:1px;color:var(--muted);padding:0}fieldset label{display:flex;align-items:center;gap:5px}
#schema{height:135px;min-height:80px;margin:12px 0;border:1px solid var(--line);border-radius:6px;background:#10191a}summary{font-size:12px;color:var(--muted);cursor:pointer}details .settings-row{padding-top:16px}#advanced{margin-top:12px}
#image-stage{position:relative;line-height:0;max-width:100%;margin:auto}#preview{display:block;width:auto;max-width:100%;height:auto}#overlay{position:absolute;inset:0;width:100%;height:100%;overflow:visible}#overlay g{transition:opacity .15s}#overlay .highlight{stroke-width:4;filter:drop-shadow(0 0 4px currentColor)}#overlay:has(.highlight) g:not(.highlight){opacity:.15}
.heading label{font-size:11px;color:var(--muted)}#placeholder{text-align:center;line-height:2}#placeholder span{font-size:11px;color:#647c79}
#result-tabs{display:flex;gap:4px;padding:10px;border-bottom:1px solid var(--line);overflow:auto}#result-tabs button{padding:7px 10px;font-size:11px;background:transparent;border-color:transparent;white-space:nowrap}#result-tabs button[aria-pressed=true]{color:var(--accent);background:#203632;border-color:#3e5f54}
#insights{height:446px;overflow:auto;padding:16px}.insight{padding:14px 16px;margin-bottom:12px;background:#192425;border:1px solid #2d3b3c;border-radius:7px}.insight h3{font-size:12px;font-weight:500;color:var(--accent);margin:0 0 10px;text-transform:capitalize}.insight pre{font:12px/1.65 ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere;margin:0;color:#bdcfca}.insight:focus-visible{outline:2px solid var(--accent)}
.counts{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:12px}.counts div{border:1px solid var(--line);border-radius:7px;padding:14px;display:flex;flex-direction:column;gap:4px}.counts strong{font-size:28px;font-weight:400;color:var(--accent)}.counts span{font-size:10px;color:var(--muted)}
.probability{display:grid;grid-template-columns:1fr auto;gap:6px;margin-top:13px;font-size:12px}.probability progress{grid-column:1/-1;width:100%;height:5px;accent-color:var(--accent)}progress::-webkit-progress-bar{background:#303d3c;border-radius:4px}progress::-webkit-progress-value{background:var(--accent);border-radius:4px}
.source{position:relative}.source.scanning::after{content:'';position:absolute;left:0;right:0;top:58px;height:1px;background:var(--accent);box-shadow:0 0 35px 8px #a2e7ce20;animation:sweep 3s ease-in-out infinite;pointer-events:none}@keyframes sweep{50%{top:98%}}@media(prefers-reduced-motion:reduce){.source.scanning::after{animation:none}}
footer{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}button:focus-visible,select:focus-visible,input:focus-visible,textarea:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
@media(max-width:760px){h1 span{display:block;font-size:19px}.model-note{margin-left:0}.settings-row{gap:12px}.settings-row label{flex-wrap:wrap}#insights{height:340px}.counts div{padding:10px}.toolbar{gap:8px}#result-tabs{flex-wrap:wrap}}
*{box-sizing:border-box}body{margin:0}main{max-width:1300px;margin:auto;padding:42px 32px}header,.toolbar,.heading{display:flex;align-items:center;gap:12px}header{justify-content:space-between;margin-bottom:30px}h1{font-size:40px;letter-spacing:-2px;margin:0;font-weight:600}.eyebrow{font-size:11px;letter-spacing:2px;text-transform:uppercase;color:var(--accent);margin:0 0 6px}a{color:var(--muted);font-size:12px;text-decoration:none}a:hover{color:var(--accent)}button,select,.file{border:1px solid var(--line);border-radius:6px;background:#1c2425;color:inherit;font:inherit;padding:10px 14px;font-size:13px}button,.file{cursor:pointer}button:disabled{opacity:.4;cursor:default}button:not(:disabled):hover,.file:hover{border-color:var(--accent)}#run{color:#101b17;background:var(--accent);border-color:var(--accent)}input[type=file]{position:absolute;width:1px;height:1px;opacity:0}.toolbar{flex-wrap:wrap}.toolbar label:not(.file){display:flex;align-items:center;gap:10px;font-size:12px;color:var(--muted)}#status{color:var(--muted);font-size:13px;margin:22px 0}#status.error{color:#ffafa9}.panels{display:grid;grid-template-columns:1fr 1fr;gap:18px}section:not(.toolbar){min-width:0}.panels>section{border:1px solid var(--line);border-radius:9px;overflow:hidden;background:#151c1d}h2{font-size:11px;letter-spacing:1.8px;text-transform:uppercase;font-weight:500;color:var(--muted);margin:0;padding:18px}.heading{border-bottom:1px solid var(--line);padding-right:12px}.heading h2{margin-right:auto}.heading button{padding:5px 9px;font-size:11px}.source>h2{border-bottom:1px solid var(--line)}.image{height:490px;overflow:auto;display:flex;align-items:center;justify-content:center;padding:16px;background:#0c1011}.image img{max-width:100%;height:auto}.image p{color:#607575;font-size:13px}textarea{display:block;width:100%;height:490px;resize:vertical;border:0;outline:0;background:transparent;color:#e0e7e5;font:13px/1.7 ui-monospace,SFMono-Regular,Consolas,monospace;padding:18px;tab-size:4;white-space:pre}textarea::placeholder{color:#607575}footer{font-size:11px;color:var(--muted);padding-top:18px;line-height:1.6}@media(max-width:760px){main{padding:25px 16px}.panels{grid-template-columns:1fr}.image,textarea{height:300px}header a{max-width:110px;text-align:right}}
"""

let render() = file
